#!/usr/bin/env node
// Writes app/demo/template-files.ts from app/demo/honeycomb/: the files a demo run's repo starts with, bundled into the
// Worker so any GitHive can run the demo without a template repo. Run it after changing app/demo/honeycomb/.
//
//   node app/scripts/demo-template.mjs [--check]     --check fails if the generated file is out of date

import { readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";

const ROOT = new URL("../..", import.meta.url).pathname;
const TEMPLATE = join(ROOT, "app/demo/honeycomb");
const OUT = join(ROOT, "app/demo/template-files.ts");

function filesIn(dir) {
	return readdirSync(dir).flatMap((name) => {
		const path = join(dir, name);
		return statSync(path).isDirectory() ? filesIn(path) : [path];
	});
}

const files = Object.fromEntries(
	filesIn(TEMPLATE)
		.sort()
		.map((path) => [relative(TEMPLATE, path), readFileSync(path, "utf8")]),
);
const source = [
	"// Generated by app/scripts/demo-template.mjs from app/demo/honeycomb/: don't edit it by hand.",
	"",
	"/** The files a Honeycomb demo run's repo starts with, by path. */",
	`export const TEMPLATE_FILES: Record<string, string> = ${JSON.stringify(files, null, "\t")};`,
	"",
].join("\n");

if (process.argv.includes("--check")) {
	if (readFileSync(OUT, "utf8") !== source) {
		console.error("app/demo/template-files.ts is out of date: run node app/scripts/demo-template.mjs");
		process.exit(1);
	}
	console.log("app/demo/template-files.ts is up to date");
} else {
	writeFileSync(OUT, source);
	console.log(`wrote ${relative(ROOT, OUT)}: ${Object.keys(files).length} files`);
}
